1	import { spawn } from 'node:child_process';
2	import { createWriteStream, type WriteStream } from 'node:fs';
3	
4	export interface ExecOptions {
5	  cwd: string;
6	  timeoutMs: number;
7	  env?: NodeJS.ProcessEnv;
8	  signal?: AbortSignal;
9	  /** Stop collecting stdout past this many bytes and kill the process. */
10	  maxBytes?: number;
11	  /**
12	   * Write stdout to this file instead of collecting it, for output that can be
13	   * too large to hold in memory. `stdout` is then empty, `bytes` says how much
14	   * was written, and `maxBytes` does not apply. The file is created with
15	   * access for its owner only.
16	   */
17	  stdoutFile?: string;
18	}
19	
20	export interface ExecResult {
21	  /** Exit code, or null when the process was killed or never started. */
22	  code: number | null;
23	  stdout: Buffer;
24	  stderr: string;
25	  timedOut: boolean;
26	  aborted: boolean;
27	  /** stdout hit `maxBytes`. */
28	  truncated: boolean;
29	  /** How many bytes of stdout the process produced before it stopped or was cut off. */
30	  bytes: number;
31	  /** Set when the process could not be started, for example ENOENT. */
32	  spawnError?: NodeJS.ErrnoException;
33	  /** Set when stdout could not be written to `stdoutFile`, for example on a full disk. */
34	  writeError?: Error;
35	}
36	
37	export type Exec = (file: string, args: readonly string[], options: ExecOptions) => Promise<ExecResult>;
38	
39	const DEFAULT_MAX_BYTES = 16 * 1024 * 1024;
40	const STDERR_CAP = 64 * 1024;
41	const KILL_GRACE_MS = 2000;
42	
43	/**
44	 * Runs a program without a shell and collects its output, or streams it to a
45	 * file.
46	 *
47	 * On POSIX the child gets its own process group, so a timeout or abort also
48	 * stops the git transports that the Entire CLI starts.
49	 */
50	export const exec: Exec = (file, args, options) =>
51	  new Promise<ExecResult>((resolve) => {
52	    const maxBytes = options.maxBytes ?? DEFAULT_MAX_BYTES;
53	    const posix = process.platform !== 'win32';
54	    const chunks: Buffer[] = [];
55	    let bytes = 0;
56	    // Collected as bytes and decoded once, so a character split across chunks survives.
57	    const stderrChunks: Buffer[] = [];
58	    let stderrSize = 0;
59	    let timedOut = false;
60	    let aborted = false;
61	    let truncated = false;
62	    let settled = false;
63	    let writeError: Error | undefined;
64	    let forceTimer: NodeJS.Timeout | undefined;
65	    let sink: WriteStream | undefined;
66	    /** Resolves once the output file has been flushed and closed. */
67	    let sinkClosed: Promise<void> = Promise.resolve();
68	
69	    if (options.signal?.aborted) {
70	      resolve({ code: null, stdout: Buffer.alloc(0), stderr: '', timedOut: false, aborted: true, truncated: false, bytes: 0 });
71	      return;
72	    }
73	
74	    const child = spawn(file, [...args], {
75	      cwd: options.cwd,
76	      env: options.env ?? process.env,
77	      shell: false,
78	      windowsHide: true,
79	      detached: posix,
80	      stdio: ['ignore', 'pipe', 'pipe'],
81	    });
82	
83	    const kill = (signal: NodeJS.Signals): void => {
84	      if (child.pid === undefined) return;
85	      try {
86	        if (posix) process.kill(-child.pid, signal);
87	        else child.kill(signal);
88	      } catch {
89	        // The process has already exited.
90	      }
91	    };
92	
