99	 * are used here, and none of them writes.
100	 *
101	 * The session calls named `remote…` read Entire's API through `entire api`,
102	 * with the same login. They pass a path and nothing else, which makes the
103	 * CLI send a GET: no method, field, or body flag is ever given.
104	 *
105	 * The brain calls run the entire-brain plugin, which may not be installed.
106	 * `status` and `viz` read the brain from disk. The commands that install the
107	 * plugin, or build or refresh a brain, are not used here.
108	 */
109	export class EntireCli {
110	  constructor(
111	    readonly binPath: string,
112	    private readonly exec: Exec,
113	    private readonly lane: Lane,
114	    private readonly log: (line: string) => void = () => {},
115	    private readonly serve: StartServer = startServer,
116	  ) {}
117	
118	  private run(cwd: string, args: string[], options: RunOptions): Promise<ExecResult> {
119	    const task = async (): Promise<ExecResult> => {
120	      const started = Date.now();
121	      const result = await this.exec(this.binPath, args, {
122	        cwd,
123	        timeoutMs: options.timeoutMs,
124	        env: { ...process.env, NO_COLOR: '1', GIT_TERMINAL_PROMPT: '0' },
125	        ...(options.signal ? { signal: options.signal } : {}),
126	        ...(options.maxBytes ? { maxBytes: options.maxBytes } : {}),
127	        ...(options.stdoutFile ? { stdoutFile: options.stdoutFile } : {}),
128	      });
129	      const outcome = result.aborted ? 'aborted' : result.timedOut ? 'timed out' : `exit ${result.code}`;
130	      this.log(`entire ${args.join(' ')} (${outcome}, ${Date.now() - started} ms)`);
131	      const stderr = result.stderr.trim();
132	      if (stderr) this.log(`  stderr: ${stderr.split('\n').slice(0, 6).join('\n          ')}`);
133	      return result;
134	    };
135	    return this.lane.run(task, {
136	      ...(options.priority ? { priority: options.priority } : {}),
137	      ...(options.dedupe ? { key: `${cwd}\x00${args.join('\x00')}` } : {}),
138	    });
139	  }
140	
141	  async version(cwd: string): Promise<Result<CliVersion>> {
142	    const result = await this.run(cwd, ['version'], { timeoutMs: 5000 });
143	    const failure = processFailure(result, 'check the Entire CLI version');
144	    if (failure) return { ok: false, failure };
145	    const version = parseCliVersion(result.stdout.toString('utf8'));
146	    return version
147	      ? ok(version)
148	      : fail('unexpectedOutput', 'The Entire CLI did not report a version.', result.stdout.toString('utf8'));
149	  }
150	
151	  /** Local only, with no side effects. Safe to call on every refresh. */
152	  async status(cwd: string): Promise<Result<StatusInfo>> {
153	    const result = await this.run(cwd, ['status', '--json'], { timeoutMs: 10_000, dedupe: true });
154	    return jsonResult(result, 'read the Entire status', readStatus);
155	  }
156	
157	  /**
158	   * Rows for the current branch. Slow when the CLI has remote checkpoints to
159	   * fetch, so it runs at background priority and nothing should await it
160	   * before drawing.
161	   */
162	  async listCheckpoints(cwd: string, limit: number): Promise<Result<CheckpointRow[]>> {
163	    const result = await this.run(cwd, ['checkpoint', 'explain', '--json', '--limit', String(limit), '--no-pager'], {
164	      timeoutMs: 90_000,
165	      priority: 'background',
166	      dedupe: true,
167	    });
168	    return jsonResult(result, 'list checkpoints', readCheckpointRows);
169	  }
170	
171	  async explainCheckpoint(cwd: string, checkpointId: string, signal?: AbortSignal): Promise<Result<CheckpointDetail>> {
172	    if (!isCheckpointId(checkpointId)) return fail('unexpectedOutput', 'That is not a checkpoint ID.');
173	    // --checkpoint forces the argument to be read as an ID. A 12-hex ID is
174	    // otherwise indistinguishable from a commit SHA prefix.
175	    const result = await this.run(cwd, ['checkpoint', 'explain', '--checkpoint', checkpointId, '--json', '--no-pager'], {
176	      timeoutMs: 45_000,
177	      ...(signal ? { signal } : {}),
178	    });
179	    return jsonResult(result, 'read the checkpoint', readCheckpointDetail);
180	  }
181	
182	  /** The CLI's own text rendering. It covers only the latest session of the checkpoint. */
183	  async fullText(cwd: string, checkpointId: string, signal?: AbortSignal): Promise<Result<string>> {
184	    if (!isCheckpointId(checkpointId)) return fail('unexpectedOutput', 'That is not a checkpoint ID.');
185	    const result = await this.run(cwd, ['checkpoint', 'explain', '--checkpoint', checkpointId, '--full', '--no-pager'], {
186	      timeoutMs: 60_000,
187	      maxBytes: TRANSCRIPT_MAX_BYTES,
188	      ...(signal ? { signal } : {}),
189	    });
190	    const failure = processFailure(result, 'read the transcript');
191	    if (failure) return { ok: false, failure };
192	    return ok(result.stdout.toString('utf8'));
193	  }
194	
195	  /**
196	   * Who the CLI names as the author of a checkpoint: the author of the commit
197	   * that carries it, or else of the commit that stored its data. Undefined
198	   * when the CLI names no one. The CLI's JSON leaves the author out, so this
199	   * reads the header of its short text view.
200	   */
201	  async checkpointAuthor(cwd: string, checkpointId: string, signal?: AbortSignal): Promise<Result<string | undefined>> {
202	    if (!isCheckpointId(checkpointId)) return fail('unexpectedOutput', 'That is not a checkpoint ID.');
203	    const result = await this.run(cwd, ['checkpoint', 'explain', '--checkpoint', checkpointId, '--short', '--no-pager'], {
204	      timeoutMs: 45_000,
205	      ...(signal ? { signal } : {}),
206	    });
207	    const failure = processFailure(result, 'read the checkpoint');
208	    if (failure) return { ok: false, failure };
209	    return ok(parseCheckpointAuthor(result.stdout.toString('utf8')));
210	  }
211	
212	  /**
213	   * Writes the stored transcript, in the agent's own format, to `file` and
214	   * returns its size in bytes. It goes to a file because the transcript of one
215	   * long session can run to hundreds of megabytes.
216	   */
217	  async rawTranscript(
218	    cwd: string,
219	    checkpointId: string,
220	    sessionIndex: number,
221	    file: string,
222	    signal?: AbortSignal,
223	  ): Promise<Result<number>> {
224	    if (!isCheckpointId(checkpointId)) return fail('unexpectedOutput', 'That is not a checkpoint ID.');
225	    if (!Number.isInteger(sessionIndex) || sessionIndex < 0) {
226	      return fail('unexpectedOutput', 'That is not a session index.');
227	    }
228	    const result = await this.run(
229	      cwd,
230	      [
231	        'checkpoint',
232	        'explain',
233	        '--checkpoint',
234	        checkpointId,
235	        '--transcript',
236	        '--session-index',
237	        String(sessionIndex),
238	        '--no-pager',
239	      ],
240	      { timeoutMs: RAW_TRANSCRIPT_TIMEOUT_MS, stdoutFile: file, ...(signal ? { signal } : {}) },
241	    );
242	    const failure = processFailure(result, 'read the raw transcript');
243	    if (failure) return { ok: false, failure };
244	    return ok(result.bytes);
245	  }
246	
247	  /** Has a side effect in the CLI: it prunes session state idle for more than seven days. */
248	  async sessionList(cwd: string): Promise<Result<SessionRow[]>> {
249	    const result = await this.run(cwd, ['session', 'list', '--json'], { timeoutMs: 15_000, dedupe: true });
250	    return jsonResult(result, 'list sessions', readSessionRows);
251	  }
252	
253	  /**
254	   * Writes the live transcript of a local session, in the agent's own format,
255	   * to `file` and returns its size in bytes.
256	   */
257	  async sessionRawTranscript(
258	    cwd: string,
259	    sessionId: string,
260	    file: string,
261	    signal?: AbortSignal,
262	  ): Promise<Result<number>> {
263	    if (!SESSION_ID.test(sessionId)) return fail('unexpectedOutput', 'That is not a session ID.');
264	    const result = await this.run(cwd, ['session', 'info', sessionId, '--transcript'], {
265	      timeoutMs: RAW_TRANSCRIPT_TIMEOUT_MS,
266	      stdoutFile: file,
267	      ...(signal ? { signal } : {}),
268	    });
269	    const failure = processFailure(result, 'read the session transcript');
270	    if (failure) return { ok: false, failure };
271	    return ok(result.bytes);
272	  }
273	
274	  /**
275	   * One page of the repository's sessions as Entire lists them, on every
276	   * branch, most recent activity first. This is the list on the Sessions
277	   * page of entire.com, with the name Entire gave each session.
278	   *
279	   * The CLI works out which repository from the `origin` remote, and reads
280	   * the cell that hosts it.
281	   */
282	  async remoteSessions(cwd: string, limit: number, cursor?: string): Promise<Result<RemoteSessionPage>> {
283	    if (!isCount(limit, 200)) return fail('unexpectedOutput', 'That is not a page size.');
284	    if (cursor !== undefined && !PAGE_TOKEN.test(cursor)) return fail('unexpectedOutput', 'That is not a page token.');
285	    const result = await this.run(cwd, ['api', '--to', 'cell', remoteSessionsPath(limit, cursor)], {
286	      timeoutMs: API_TIMEOUT_MS,
287	      dedupe: true,
288	    });
289	    return apiResult(result, 'list the sessions on Entire', readRemoteSessionPage, {
290	      notFound: 'Entire does not list sessions for this repository.',
291	    });
292	  }
293	
294	  /**
295	   * The checkpoints of one session as its page on entire.com lists them,
296	   * newest first. Entire sends them with the session's transcript, so this
297	   * is a slow call for a long session.
298	   */
299	  async remoteSessionCheckpoints(cwd: string, sessionId: string, signal?: AbortSignal): Promise<Result<RemoteCheckpoint[]>> {
300	    if (!SESSION_ID.test(sessionId)) return fail('unexpectedOutput', 'That is not a session ID.');
301	    const result = await this.run(cwd, ['api', '--to', 'cell', remoteSessionCheckpointsPath(sessionId)], {
302	      timeoutMs: API_TRANSCRIPT_TIMEOUT_MS,
303	      maxBytes: API_TRANSCRIPT_MAX_BYTES,
304	      ...(signal ? { signal } : { dedupe: true }),
305	    });
306	    return apiResult(result, 'list the checkpoints of the session on Entire', readRemoteCheckpoints, {
307	      notFound: 'Entire could not find this session.',
308	    });
309	  }
310	
311	  /** Whether the repository has a brain, as the entire-brain plugin reports it. Reads local state only. */
312	  async brainStatus(cwd: string, signal?: AbortSignal): Promise<Result<BrainStatus>> {
313	    const result = await this.run(cwd, ['brain', 'status', '--json'], {
314	      timeoutMs: 30_000,
315	      ...(signal ? { signal } : { dedupe: true }),
316	    });
317	    // Without the plugin the CLI does not know the command, and says so with its usage text.
318	    if (result.code !== 0 && result.code !== null && isPluginMissing(result.stderr)) {
319	      return fail('pluginMissing', NO_BRAIN_PLUGIN, lastLines(result.stderr));
320	    }
321	    return jsonResult(result, 'read the brain status', readBrainStatus);
322	  }
323	
324	  /**
325	   * Starts `entire brain viz`, the plugin's graph page for a repository, and
326	   * resolves with its address once it is listening. The page is served on
327	   * the loopback address, from the brain on disk, until the caller stops it.
328	   *
329	   * It takes no lane: the lanes bound how many short calls run at once, and
330	   * this one stays up for as long as the page is in use.
331	   */
332	  async startBrainViz(cwd: string, signal?: AbortSignal): Promise<Result<RunningServer>> {
333	    const started = Date.now();
334	    const server = await this.serve(this.binPath, BRAIN_VIZ_ARGS, {
335	      cwd,
336	      env: { ...process.env, NO_COLOR: '1', GIT_TERMINAL_PROMPT: '0' },
337	      ready: parseVizUrl,
338	      readyTimeoutMs: BRAIN_VIZ_READY_MS,
339	      ...(signal ? { signal } : {}),
340	    });
341	    const command = `entire ${BRAIN_VIZ_ARGS.join(' ')}`;
342	    if (server.ok) {
343	      this.log(`${command} (listening on ${server.value.url} after ${Date.now() - started} ms)`);
344	      void server.value.exited.then(() => this.log(`${command} (stopped)`));
345	      return server;
346	    }
347	    const { failure } = server;
348	    this.log(`${command} (${failure.kind}, ${Date.now() - started} ms)`);
349	    if (failure.detail) this.log(`  stderr: ${lastLines(failure.detail, 6).split('\n').join('\n          ')}`);
350	    if (failure.kind === 'exit' && isPluginMissing(failure.detail ?? '')) {
351	      return fail('pluginMissing', NO_BRAIN_PLUGIN, lastLines(failure.detail ?? ''));
352	    }
353	    if (failure.kind === 'cliMissing') return fail('cliMissing', 'The Entire CLI could not be started.', failure.detail);
354	    if (failure.kind === 'timeout') return fail('timeout', 'The Entire CLI took too long to start the brain graph.', failure.detail);
355	    if (failure.kind === 'exit') {
356	      return fail('exit', 'The Entire CLI could not start the brain graph.', lastLines(failure.detail ?? ''));
357	    }
358	    return server;
359	  }
360	
361	  /**
362	   * One page of the trails that touch a repository, most recent activity
363	   * first: the open ones, the closed ones, or with `all`, both. Those are
364	   * the only ways the CLI lists them. Trail calls read entire.io with the
365	   * login the CLI has saved.
366	   */
367	  async listTrails(
368	    cwd: string,
369	    scope: TrailScope,
370	    status: TrailListStatus,
371	    limit: number,
372	    pageToken?: string,
373	  ): Promise<Result<TrailPage>> {
374	    if (!TRAIL_PROJECT.test(scope.project) || !TRAIL_REPO.test(scope.repo)) {
375	      return fail('unexpectedOutput', 'That is not a repository on Entire.');
376	    }
377	    if (!isCount(limit, 100)) return fail('unexpectedOutput', 'That is not a page size.');
378	    if (pageToken !== undefined && !PAGE_TOKEN.test(pageToken)) {
379	      return fail('unexpectedOutput', 'That is not a page token.');
380	    }
381	    const args = [
382	      'trail',
383	      'list',
384	      '--project',
385	      scope.project,
386	      '--repo',
387	      scope.repo,
388	      // With no status the CLI lists every trail, open and closed.
389	      ...(status === 'all' ? [] : ['--status', status === 'closed' ? 'closed' : 'open']),
390	      '--limit',
391	      String(limit),
392	      '--json',
393	      ...(pageToken ? [`--page-token=${pageToken}`] : []),
394	    ];
395	    const result = await this.run(cwd, args, { timeoutMs: TRAIL_TIMEOUT_MS, dedupe: true });
396	    return jsonResult(result, 'list trails', readTrailPage, TRAIL_FAILURES);
397	  }
398	
399	  /** One trail with its changes, their merge gates and CI runs, and its page on the web. */
400	  async showTrail(cwd: string, project: string, trail: TrailRef, signal?: AbortSignal): Promise<Result<TrailDetail>> {
401	    if (!TRAIL_PROJECT.test(project)) return fail('unexpectedOutput', 'That is not a project on Entire.');
402	    const name = trailArg(trail);
403	    if (name === undefined) return fail('unexpectedOutput', 'That is not a trail number.');
404	    const result = await this.run(cwd, ['trail', 'show', name, '--project', project, '--json'], {
405	      timeoutMs: TRAIL_TIMEOUT_MS,
406	      ...(signal ? { signal } : { dedupe: true }),
407	    });
408	    return jsonResult(result, 'read the trail', readTrailDetail, TRAIL_FAILURES);
409	  }
410	
411	  /**
412	   * One page of the activity on a change, newest first.
413	   *
414	   * A change is named by its repository and its own number, which is not the
415	   * trail's number. Given a trail instead, the CLI picks the change, which a
416	   * caller can rely on only for a trail with one change. A later page is
417	   * asked for the way the first one was.
418	   */
419	  async trailTimeline(
420	    cwd: string,
421	    project: string,
422	    of: TimelineOf,
423	    limit: number,
424	    pageToken?: string,
425	    signal?: AbortSignal,
426	  ): Promise<Result<TrailTimeline>> {
427	    if (!TRAIL_PROJECT.test(project)) return fail('unexpectedOutput', 'That is not a project on Entire.');
428	    let name: string;
429	    if ('trail' in of) {
430	      const trail = trailArg(of.trail);
431	      if (trail === undefined) return fail('unexpectedOutput', 'That is not a trail number.');
432	      name = trail;
433	    } else {
434	      if (!REPO_NAME.test(of.repository)) return fail('unexpectedOutput', 'That is not a repository on Entire.');
435	      if (!isCount(of.number, Number.MAX_SAFE_INTEGER)) return fail('unexpectedOutput', 'That is not a change number.');
436	      name = `${of.repository}/${of.number}`;
437	    }
438	    if (!isCount(limit, 100)) return fail('unexpectedOutput', 'That is not a page size.');
439	    if (pageToken !== undefined && !PAGE_TOKEN.test(pageToken)) {
440	      return fail('unexpectedOutput', 'That is not a page token.');
441	    }
442	    const args = [
443	      'trail',
444	      'timeline',
445	      name,
446	      '--project',
447	      project,
448	      '--limit',
449	      String(limit),
450	      '--json',
451	      ...(pageToken ? [`--page-token=${pageToken}`] : []),
452	    ];
453	    const result = await this.run(cwd, args, { timeoutMs: TRAIL_TIMEOUT_MS, ...(signal ? { signal } : {}) });
454	    return jsonResult(result, 'read the trail timeline', readTrailTimeline, TRAIL_FAILURES);
455	  }
456	}
457	
458	/** How a failed call is worded, for calls that are not about a checkpoint. */
459	interface FailureWording {
460	  /** The call reads entire.io, so it can fail for want of a login or of access. */
461	  remote?: boolean;
462	  /** What to say when the CLI reports that the thing asked for does not exist. */
463	  notFound?: string;
464	  /** What to say when entire.io does not have the thing, or the saved login cannot see it. */
465	  noAccess?: string;
466	}
467	
468	const TRAIL_FAILURES: FailureWording = { remote: true, notFound: 'Entire could not find this trail.' };
469	
470	function lastLines(text: string, count = 3): string {
471	  return text.trim().split('\n').slice(-count).join('\n');
472	}
473	
474	/** Maps a finished process to a failure, or undefined when it exited cleanly. */
475	function processFailure(result: ExecResult, action: string, wording: FailureWording = {}): Failure | undefined {
476	  if (result.spawnError) {
477	    return {
478	      kind: 'cliMissing',
479	      message: 'The Entire CLI could not be started.',
480	      detail: result.spawnError.message,
481	    };
482	  }
483	  if (result.aborted) return { kind: 'aborted', message: 'Cancelled.' };
484	  if (result.timedOut) return { kind: 'timeout', message: `The Entire CLI took too long to ${action}.` };
485	  if (result.truncated) return { kind: 'unexpectedOutput', message: 'The Entire CLI returned more data than expected.' };
486	  if (result.writeError) {
487	    return { kind: 'exit', message: `Entire could not save what the CLI returned.`, detail: result.writeError.message };
488	  }
489	  if (result.code !== 0) {
490	    const stderr = lastLines(result.stderr);
491	    if (wording.remote) {
492	      if (/not logged in|entire login|re-authenticate/i.test(stderr)) {
493	        return { kind: 'notLoggedIn', message: 'You are not logged in to Entire.', detail: stderr };
494	      }
495	      // The second and third are what `entire api` says of an origin it cannot place on Entire.
496	      if (/does not exist or is not visible|no active mirror|needs a GitHub repo/i.test(stderr)) {
497	        return {
498	          kind: 'noAccess',
499	          message: wording.noAccess ?? 'This project is not on Entire, or your login cannot see it.',
500	          detail: stderr,
501	        };
502	      }
503	    }
504	    // For a change, the CLI says "no change <repo>/<n> found".
505	    const missing = wording.remote ? /not found|\bno (change|trail)\b[^\n]*\bfound\b/i : /not found/i;
506	    if (missing.test(stderr)) {
507	      return {
508	        kind: 'notFound',
509	        message: wording.notFound ?? 'Entire has no session data for this checkpoint, on this machine or on the remote.',
510	        detail: stderr,
511	      };
512	    }
513	    return { kind: 'exit', message: `The Entire CLI could not ${action}.`, detail: stderr };
514	  }
515	  return undefined;
516	}
517	
518	/**
519	 * Reads the reply to an `entire api` call. A call that Entire refuses exits
520	 * non-zero with the refusal as JSON on stdout, so here the exit code is
521	 * looked at first, and the refusal is read for what went wrong.
522	 */
523	function apiResult<T>(
524	  result: ExecResult,
525	  action: string,
526	  read: (value: unknown) => T | undefined,
527	  wording: FailureWording = {},
528	): Result<T> {
529	  const text = result.stdout.toString('utf8').trim();
530	  const refusal = result.code === 0 ? undefined : remoteRefusal(text);
531	  const failure = processFailure(
532	    refusal === undefined ? result : { ...result, stderr: `${result.stderr.trim()}\n${refusal}`.trim() },
533	    action,
534	    { remote: true, noAccess: 'This repository is not on Entire, or your login cannot see it.', ...wording },
535	  );
536	  if (failure) {
537	    // The API answers an expired or missing token in its own words, not the CLI's.
538	    if (failure.kind === 'exit' && /\b(unauthori[sz]ed|unauthenticated|invalid token|token (has )?expired)\b/i.test(refusal ?? '')) {
539	      return fail('notLoggedIn', 'You are not logged in to Entire.', failure.detail);
540	    }
541	    return { ok: false, failure };
542	  }
543	  let parsed: unknown;
544	  try {
545	    parsed = JSON.parse(text);
546	  } catch {
547	    return fail('unexpectedOutput', `Entire returned no data when asked to ${action}.`, text.slice(0, 400));
548	  }
549	  const value = read(parsed);
550	  return value === undefined
551	    ? fail('unexpectedOutput', 'Entire returned data this extension does not understand.', text.slice(0, 400))
552	    : ok(value);
553	}
554	
555	/**
556	 * Parses stdout as JSON before looking at the exit code: the CLI exits
557	 * non-zero for a partially readable checkpoint while still printing a usable
558	 * envelope. In a repo where Entire is disabled it prints prose and exits 0.
559	 */
560	function jsonResult<T>(
561	  result: ExecResult,
562	  action: string,
563	  read: (value: unknown) => T | undefined,
564	  wording: FailureWording = {},
565	): Result<T> {
566	  const text = result.stdout.toString('utf8').trim();
567	  if (text !== '' && !result.aborted && !result.timedOut && !result.truncated) {
568	    let parsed: unknown;
569	    let valid = true;
570	    try {
571	      parsed = JSON.parse(text);
572	    } catch {
573	      valid = false;
574	    }
575	    if (valid) {
576	      const value = read(parsed);
577	      if (value !== undefined) return ok(value);
578	      return fail('unexpectedOutput', `The Entire CLI returned data this extension does not understand.`, text.slice(0, 400));
579	    }
580	    if (/entire is (disabled|not enabled)|entire enable/i.test(text)) {
581	      return fail('notEnabled', 'Entire is not enabled in this repository.', text.slice(0, 400));
582	    }
583	  }
584	  const failure = processFailure(result, action, wording);
585	  if (failure) return { ok: false, failure };
586	  return fail('unexpectedOutput', `The Entire CLI returned no data when asked to ${action}.`, text.slice(0, 400));
587	}
