1	/**
2	 * The repository brain, which the entire-brain plugin builds and serves.
3	 *
4	 * The extension reads two things from the plugin, both through the Entire
5	 * CLI as `entire brain …`: whether a repository has a brain, and where the
6	 * plugin's local graph page is once `entire brain viz` has started. The
7	 * plugin is run through the CLI and never by its own name, because the CLI
8	 * finds the copy it manages, which can be newer than one on `PATH`.
9	 */
10	
11	/** `entire brain viz`, told not to open a browser itself and to pick a free port. */
12	export const BRAIN_VIZ_ARGS: readonly string[] = ['brain', 'viz', '--no-open', '--port', '0'];
13	
14	/** `entire brain status --json`, as far as the extension uses it. */
15	export interface BrainStatus {
16	  /**
17	   * `current` for a brain that is built, and `absent` for a repository that
18	   * has none. The plugin also reports `corrupt`, `unsafe`, and `unsupported`.
19	   */
20	  manifestState: string;
21	  /** When the brain was last written, as an ISO time. */
22	  generatedAt?: string;
23	  /** The size of the code graph, which is what `entire brain viz` draws. */
24	  files?: number;
25	  symbols?: number;
26	  relations?: number;
27	  /** Durable memories in the brain. The plugin's report calls them facts. */
28	  memories?: number;
29	  /** Exchanges from retained sessions that the brain has indexed. */
30	  exchanges?: number;
31	  docsRecords?: number;
32	  docsFiles?: number;
33	  /** The worst the plugin says of any part of the brain: `ok`, `degraded`, or `unsafe`. */
34	  freshness?: string;
35	  /** The parts that are not fresh, each with the plugin's reason. */
36	  staleParts: string[];
37	  /** The plugin's background updater for this machine. */
38	  updater?: 'running' | 'stopped' | 'notInstalled';
39	  /** `connected` when the repository is bound to a hosted brain. */
40	  hosted?: string;
41	  hostedSynced?: boolean;
42	  warnings: string[];
43	}
44	
45	function isObject(value: unknown): value is Record<string, unknown> {
46	  return typeof value === 'object' && value !== null && !Array.isArray(value);
47	}
48	
49	function part(value: unknown): Record<string, unknown> {
50	  return isObject(value) ? value : {};
51	}
52	
53	function count(value: unknown): number | undefined {
54	  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : undefined;
55	}
56	
57	function text(value: unknown): string | undefined {
58	  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
59	}
60	
61	/** How bad a freshness word is. A word the plugin adds later counts as worse than `ok`. */
62	function badness(severity: string): number {
63	  return severity === 'ok' ? 0 : severity === 'unsafe' ? 2 : 1;
64	}
65	
66	const MAX_NOTES = 10;
67	const NOTE_CHARS = 400;
68	
69	/** Reads the plugin's status report. Undefined when it does not say what state the brain is in. */
70	export function readBrainStatus(value: unknown): BrainStatus | undefined {
71	  if (!isObject(value) || !isObject(value.brain)) return undefined;
72	  const state = value.brain.manifest_state;
73	  if (typeof state !== 'string' || state === '') return undefined;
74	  const status: BrainStatus = { manifestState: state, staleParts: [], warnings: [] };
75	  const generatedAt = text(value.brain.generated_at);
76	  if (generatedAt) status.generatedAt = generatedAt;
77	
78	  const semantic = part(value.semantic);
79	  const coverage = part(semantic.coverage);
80	  for (const key of ['files', 'symbols', 'relations'] as const) {
81	    const found = count(coverage[key]);
82	    if (found !== undefined) status[key] = found;
83	  }
84	  const memories = count(part(value.facts).facts);
85	  if (memories !== undefined) status.memories = memories;
86	  const retrieval = part(value.retrieval);
87	  const exchanges = count(part(retrieval.conversation).exchanges);
88	  if (exchanges !== undefined) status.exchanges = exchanges;
89	  const docsRecords = count(retrieval.docs_records);
90	  if (docsRecords !== undefined) status.docsRecords = docsRecords;
91	  const docsFiles = count(retrieval.docs_files);
92	  if (docsFiles !== undefined) status.docsFiles = docsFiles;
93	
94	  // The code graph and the indexes each report their own freshness. The view shows the worst.
95	  for (const source of [semantic, retrieval]) {
96	    const freshness = part(source.freshness);
97	    const severity = text(freshness.severity);
98	    if (severity && (status.freshness === undefined || badness(severity) > badness(status.freshness))) {
99	      status.freshness = severity;
100	    }
101	    for (const [name, axis] of Object.entries(part(freshness.axes))) {
102	      const axisState = text(part(axis).state);
103	      if (!axisState || axisState === 'ok' || status.staleParts.length >= MAX_NOTES) continue;
104	      const detail = text(part(axis).detail);
105	      status.staleParts.push(`${name}: ${detail ?? axisState}`.slice(0, NOTE_CHARS));
106	    }
107	  }
108	
109	  const onboarding = part(value.onboarding);
110	  if (isObject(onboarding.daemon)) {
111	    const daemon = onboarding.daemon;
112	    status.updater = daemon.running === true ? 'running' : daemon.installed === true ? 'stopped' : 'notInstalled';
113	  }
114	  const hosted = part(value.hosted);
115	  const hostedState = text(hosted.state);
116	  if (hostedState) status.hosted = hostedState;
117	  if (typeof hosted.synced === 'boolean') status.hostedSynced = hosted.synced;
118	
119	  if (Array.isArray(value.warnings)) {
120	    for (const warning of value.warnings) {
121	      const note = text(warning);
122	      if (note && status.warnings.length < MAX_NOTES) status.warnings.push(note.slice(0, NOTE_CHARS));
123	    }
124	  }
125	  return status;
126	}
