128	/** One line of the Brain view: a fact about the brain of a repository. */
129	export interface BrainDetail {
130	  key: 'state' | 'graph' | 'memories' | 'conversations' | 'docs' | 'freshness' | 'updates' | 'hosted' | 'warning';
131	  label: string;
132	  value: string;
133	  /** More than fits on the line. */
134	  tooltip?: string;
135	  /** The line reports something that needs a look. */
136	  attention?: boolean;
137	}
138	
139	const number = (value: number): string => value.toLocaleString('en-US');
140	const plural = (value: number, one: string, many: string): string => `${number(value)} ${value === 1 ? one : many}`;
141	const sentence = (value: string): string => {
142	  const words = value.replace(/[_-]+/g, ' ').trim();
143	  return words.charAt(0).toUpperCase() + words.slice(1);
144	};
145	
146	/**
147	 * What the Brain view lists for a repository that has a brain, in the order
148	 * it lists it. `updated` is the age of the brain in words, such as "2h ago",
149	 * which the caller works out.
150	 */
151	export function brainDetails(status: BrainStatus, updated = ''): BrainDetail[] {
152	  const details: BrainDetail[] = [];
153	  const built = status.manifestState === 'current';
154	  details.push({
155	    key: 'state',
156	    label: 'Brain',
157	    value: [built ? 'Built' : sentence(status.manifestState), updated ? `updated ${updated}` : ''].filter(Boolean).join(' · '),
158	    ...(built ? {} : { attention: true, tooltip: 'Run "entire brain status" in a terminal for the details.' }),
159	  });
160	
161	  const graph = [
162	    status.files === undefined ? '' : plural(status.files, 'file', 'files'),
163	    status.symbols === undefined ? '' : plural(status.symbols, 'symbol', 'symbols'),
164	    status.relations === undefined ? '' : plural(status.relations, 'relation', 'relations'),
165	  ].filter(Boolean);
166	  if (graph.length > 0) details.push({ key: 'graph', label: 'Code graph', value: graph.join(' · ') });
167	  if (status.memories !== undefined) details.push({ key: 'memories', label: 'Memories', value: number(status.memories) });
168	  if (status.exchanges !== undefined) {
169	    details.push({ key: 'conversations', label: 'Conversations', value: plural(status.exchanges, 'exchange', 'exchanges') });
170	  }
171	  if (status.docsRecords !== undefined) {
172	    const from = status.docsFiles === undefined ? '' : ` from ${plural(status.docsFiles, 'file', 'files')}`;
173	    details.push({ key: 'docs', label: 'Docs', value: `${plural(status.docsRecords, 'record', 'records')}${from}` });
174	  }
175	
176	  if (status.freshness !== undefined) {
177	    const fresh = status.freshness === 'ok';
178	    details.push({
179	      key: 'freshness',
180	      label: 'Freshness',
181	      value: fresh ? 'Up to date' : sentence(status.freshness),
182	      ...(fresh ? {} : { attention: true }),
183	      ...(status.staleParts.length > 0 ? { tooltip: status.staleParts.join('\n') } : {}),
184	    });
185	  }
186	  if (status.updater !== undefined) {
187	    details.push({
188	      key: 'updates',
189	      label: 'Updates',
190	      value:
191	        status.updater === 'running'
192	          ? 'Running in the background'
193	          : status.updater === 'stopped'
194	            ? 'Not running'
195	            : 'Not installed',
196	      ...(status.updater === 'stopped' ? { attention: true } : {}),
197	    });
198	  }
199	  if (status.hosted !== undefined) {
200	    const connected = status.hosted === 'connected';
201	    const synced = !connected || status.hostedSynced === undefined ? '' : status.hostedSynced ? ' · synced' : ' · not synced';
202	    details.push({
203	      key: 'hosted',
204	      label: 'Hosted brain',
205	      value: `${connected ? 'Connected' : status.hosted === 'disconnected' ? 'Not connected' : sentence(status.hosted)}${synced}`,
206	    });
207	  }
208	  for (const warning of status.warnings) {
209	    details.push({ key: 'warning', label: 'Warning', value: warning, tooltip: warning, attention: true });
210	  }
211	  return details;
212	}
