2	import { hasBrain, type BrainStatus } from '../core/brain';
3	import { fail, type Failure } from '../core/errors';
4	import type { RunningServer } from '../core/serverProcess';
5	import type { RepoContext, RepoManager } from './repoManager';
6	
7	/** How a request to open the brain graph ended. The caller words the message. */
8	export type BrainOutcome =
9	  /** The page is open. `started` says whether a server had to be started for it. */
10	  | { kind: 'opened'; url: string; started: boolean }
11	  /** The entire-brain plugin is not installed. */
12	  | { kind: 'pluginMissing' }
13	  /** The repository has no brain yet. */
14	  | { kind: 'noBrain' }
15	  | { kind: 'cancelled' }
16	  | { kind: 'failed'; message: string };
17	
18	/** What the Brain view shows: the brain's details, or the reason it has none. */
19	export type BrainViewState = 'loading' | 'pluginMissing' | 'noBrain' | 'failed' | 'ready';
20	
21	/** What is known about the brain of one repository, as far as it has been read. */
22	export interface BrainInfo {
23	  loading: boolean;
24	  /** The plugin's last report. Kept while a fresh one is read. */
25	  status?: BrainStatus;
26	  /** Why the last read gave no report. */
27	  failure?: Failure;
28	}
29	
30	interface Running {
31	  server: RunningServer;
32	  /** The branch that was checked out when the server started. It reads the branch once. */
33	  branch: string | undefined;
34	}
35	
36	/**
37	 * The brain of each open repository: what the entire-brain plugin reports
38	 * about it, for the Brain view, and the plugin's graph page.
39	 *
40	 * The report is read when the Brain view is first shown and on Refresh, and
41	 * not before: the view starts collapsed, and a repository may have no brain.
42	 *
43	 * The graph page is the one `entire brain viz` serves on the loopback
44	 * address. It opens in the browser. It cannot be shown in an editor tab,
45	 * because the plugin's server forbids every other page from framing it
46	 * (`frame-ancestors 'none'`). The server runs until it is stopped, so this
47	 * owns one per repository and stops them all when the window closes.
48	 *
49	 * Nothing here installs the plugin or builds a brain: both write, and the
50	 * extension only reads.
51	 */
52	export class BrainService implements vscode.Disposable {
53	  /**
54	   * Opens a page of a server on this machine. The address goes through
55	   * `asExternalUri` first, which forwards the port when the extension runs
56	   * on another machine than the browser. The extension-host tests replace
57	   * this, so that no browser opens.
58	   */
59	  openUrl: (url: string) => Thenable<unknown> = async (url) =>
60	    vscode.env.openExternal(await vscode.env.asExternalUri(vscode.Uri.parse(url, true)));
61	
62	  private readonly info = new Map<string, BrainInfo>();
63	  /** Counts the reads of each repository's report, so a late answer to an earlier one is dropped. */
64	  private readonly reads = new Map<string, number>();
65	  private readonly servers = new Map<string, Running>();
66	  /** Starts under way, by repository, so that two requests share one. */
67	  private readonly starting = new Map<string, Promise<BrainOutcome>>();
68	  private readonly changed = new vscode.EventEmitter<void>();
69	  /** Fires when a report arrives or a server starts or stops. */
70	  readonly onDidChange = this.changed.event;
71	  private readonly subscription: vscode.Disposable;
72	  private disposed = false;
73	
74	  constructor(
75	    private readonly manager: RepoManager,
76	    private readonly log: vscode.LogOutputChannel,
77	  ) {
78	    // A repository that leaves the window takes its report and its server with it.
79	    this.subscription = manager.onDidChange(() => {
80	      let dropped = false;
81	      for (const root of new Set([...this.servers.keys(), ...this.info.keys()])) {
82	        if (manager.repoFor(root)) continue;
83	        this.servers.get(root)?.server.stop();
84	        this.servers.delete(root);
85	        this.info.delete(root);
86	        dropped = true;
87	      }
88	      // The state the view shows also depends on which repositories have Entire enabled.
89	      this.sync();
90	      if (dropped) this.changed.fire();
91	    });
92	    this.sync();
93	  }
94	
95	  /** What has been read about the brain of a repository. Undefined until the Brain view asks. */
96	  details(root: string): BrainInfo | undefined {
97	    return this.info.get(root);
98	  }
99	
100	  /**
101	   * What the Brain view shows. With one repository, a brain that cannot be
102	   * listed leaves the view empty and this says why. With several, each
103	   * repository has a row of its own and says so under it.
104	   */
105	  state(): BrainViewState {
106	    const repos = this.manager.enabledRepos;
107	    if (repos.length !== 1 || !repos[0]) return 'ready';
108	    return this.stateOf(repos[0].root);
109	  }
110	
111	  /** The same, for one repository. */
112	  stateOf(root: string): BrainViewState {
113	    const info = this.info.get(root);
114	    if (!info || (info.loading && !info.status && !info.failure)) return 'loading';
115	    if (info.status) return hasBrain(info.status) ? 'ready' : 'noBrain';
116	    return info.failure?.kind === 'pluginMissing' ? 'pluginMissing' : 'failed';
117	  }
118	
119	  /**
120	   * Reads the report of each repository that has not been asked about yet.
121	   * The Brain view calls this when it is shown.
122	   */
123	  ensureStatus(): void {
124	    for (const repo of this.manager.enabledRepos) {
125	      if (!this.info.has(repo.root)) void this.loadStatus(repo);
126	    }
127	  }
128	
129	  /** Reads again every report that has been read. Refresh calls this. */
130	  refresh(): void {
131	    for (const root of [...this.info.keys()]) {
132	      const repo = this.manager.repoFor(root);
133	      if (repo) void this.loadStatus(repo);
134	    }
135	  }
136	
137	  /** Reads the plugin's report on one repository. The one already shown stays until the answer arrives. */
138	  async loadStatus(repo: RepoContext, signal?: AbortSignal): Promise<BrainInfo> {
139	    const cli = this.manager.cli;
140	    const read = (this.reads.get(repo.root) ?? 0) + 1;
141	    this.reads.set(repo.root, read);
142	    const before = this.info.get(repo.root);
143	    const pending: BrainInfo = { ...before, loading: true };
144	    this.info.set(repo.root, pending);
145	    this.announce();
146	
147	    const result = cli
148	      ? await cli.brainStatus(repo.root, signal)
149	      : fail<BrainStatus>('cliMissing', 'The Entire CLI is not available.');
150	    // A newer read, or the repository leaving the window, makes this answer stale.
151	    if (this.reads.get(repo.root) !== read || this.info.get(repo.root) !== pending) {
152	      return this.info.get(repo.root) ?? { loading: false };
153	    }
154	    if (!result.ok && result.failure.kind === 'aborted') {
155	      // A cancelled read says nothing new. What was known before still stands.
156	      if (before) this.info.set(repo.root, { ...before, loading: false });
157	      else this.info.delete(repo.root);
158	      this.announce();
159	      return this.info.get(repo.root) ?? { loading: false, failure: result.failure };
160	    }
161	    const next: BrainInfo = result.ok ? { loading: false, status: result.value } : { loading: false, failure: result.failure };
162	    if (!result.ok && result.failure.kind !== 'pluginMissing') {
163	      this.log.warn(`${repo.name}: ${result.failure.message} ${result.failure.detail ?? ''}`.trim());
164	    }
165	    this.info.set(repo.root, next);
166	    this.announce();
167	    return next;
168	  }
169	
170	  /** Whether a graph server is up, for one repository or for any. */
171	  running(root?: string): boolean {
172	    return root === undefined ? this.servers.size > 0 : this.servers.has(root);
173	  }
174	
175	  /** The address of the repository's graph page, while its server runs. */
176	  url(root: string): string | undefined {
177	    return this.servers.get(root)?.server.url;
178	  }
179	
180	  /** Whether opening the graph has to start a server first, which takes a moment. */
181	  needsStart(repo: RepoContext): boolean {
182	    const running = this.servers.get(repo.root);
183	    return !running || running.branch !== repo.branch;
184	  }
185	
186	  /**
187	   * Opens the graph of a repository's brain, starting its server when none
188	   * runs. `signal` gives up on a start that is still under way.
189	   */
190	  async open(repo: RepoContext, signal?: AbortSignal): Promise<BrainOutcome> {
191	    if (this.disposed) return { kind: 'cancelled' };
192	    const running = this.servers.get(repo.root);
193	    if (running && running.branch === repo.branch) {
194	      await this.openUrl(running.server.url);
195	      return { kind: 'opened', url: running.server.url, started: false };
196	    }
197	    // The server read the branch when it started. Another branch needs another server.
198	    if (running) this.stop(repo.root);
199	
200	    let start = this.starting.get(repo.root);
201	    if (!start) {
202	      start = this.start(repo, signal).finally(() => this.starting.delete(repo.root));
203	      this.starting.set(repo.root, start);
204	    }
205	    return start;
206	  }
207	
208	  private async start(repo: RepoContext, signal?: AbortSignal): Promise<BrainOutcome> {
209	    const cli = this.manager.cli;
210	    if (!cli) return { kind: 'failed', message: 'The Entire CLI is not available.' };
211	
212	    // The server would start without a brain and show an empty page, so the report is read first.
213	    const info = await this.loadStatus(repo, signal);
214	    if (signal?.aborted) return { kind: 'cancelled' };
215	    if (info.status) {
216	      if (!hasBrain(info.status)) return { kind: 'noBrain' };
217	    } else if (info.failure?.kind === 'pluginMissing') {
218	      return { kind: 'pluginMissing' };
219	    }
220	    // Any other failure to read the report is no reason not to try: the page says what the brain holds.
221	
222	    const started = await cli.startBrainViz(repo.root, signal);
223	    if (!started.ok) {
224	      if (started.failure.kind === 'pluginMissing') return { kind: 'pluginMissing' };
225	      if (started.failure.kind === 'aborted') return { kind: 'cancelled' };
226	      this.log.warn(`${repo.name}: ${started.failure.message} ${started.failure.detail ?? ''}`.trim());
227	      return { kind: 'failed', message: started.failure.message };
228	    }
229	    const server = started.value;
230	    if (this.disposed || !this.manager.repoFor(repo.root)) {
231	      // The window closed, or the repository left it, while the server started.
232	      server.stop();
233	      return { kind: 'cancelled' };
234	    }
235	    this.servers.set(repo.root, { server, branch: repo.branch });
236	    void server.exited.then(() => {
237	      if (this.servers.get(repo.root)?.server !== server) return;
238	      this.servers.delete(repo.root);
239	      this.announce();
240	    });
241	    this.announce();
242	    await this.openUrl(server.url);
243	    return { kind: 'opened', url: server.url, started: true };
244	  }
245	
246	  /** Stops the graph server of one repository, or every server. */
247	  stop(root?: string): void {
248	    for (const key of root === undefined ? [...this.servers.keys()] : [root]) {
249	      this.servers.get(key)?.server.stop();
250	      this.servers.delete(key);
251	    }
252	    this.announce();
253	  }
254	
255	  dispose(): void {
256	    this.disposed = true;
257	    this.subscription.dispose();
258	    this.stop();
259	    this.changed.dispose();
260	  }
261	
262	  /** Publishes what the Brain view and the Stop command depend on, then redraws the view. */
263	  private announce(): void {
264	    this.sync();
265	    if (!this.disposed) this.changed.fire();
266	  }
267	
268	  private sync(): void {
269	    void vscode.commands.executeCommand('setContext', 'entire.brainRunning', this.servers.size > 0);
270	    void vscode.commands.executeCommand('setContext', 'entire.brainState', this.state());
271	  }
272	}
